  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  font-weight: 800;
  color: var(--gray-900);
  flex-shrink: 0;
  box-shadow: 0 4px 16px rgba(255,183,0,0.3);
}

/* ===== Attractions Recommended ===== */
.attraction-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.attraction-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
