  background: var(--blue-light);
  color: var(--navy);
  font-size: 0.85rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.attraction-info h4 {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--gray-900);
}

.attraction-info span {
  font-size: 0.8rem;
  color: var(--gray-600);
}

/* ===== Account CTA ===== */
.account-cta {
  background: var(--blue-light);
  border-radius: var(--radius-lg);
  padding: 40px;
  text-align: center;
}

.account-cta h2 {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--navy);
  margin-bottom: 4px;
}

.account-cta .sub {
  color: var(--blue);
  font-weight: 600;
  margin-bottom: 8px;
}

.account-cta p {
  color: var(--gray-600);
  margin-bottom: 20px;
}

.account-cta .btn-group {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.btn-blue {
  background: var(--navy);
  color: var(--white);
  font-size: 0.9rem;
  font-weight: 700;
  padding: 12px 28px;
  border-radius: var(--radius-sm);
  transition: background var(--transition);
}

.btn-blue:hover { background: var(--navy-dark); }

.btn-outline-blue {
  background: transparent;
  color: var(--navy);
  font-size: 0.9rem;
  font-weight: 600;
  padding: 12px 28px;
  border: 2px solid var(--navy);
  border-radius: var(--radius-sm);
  transition: all var(--transition);
}

.btn-outline-blue:hover { background: var(--navy); color: var(--white); }

/* ===== Section Variants ===== */
.section--gray { background: var(--gray-50); }
.section--blue { background: var(--blue-light); }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .trust-badges-inner { grid-template-columns: repeat(2, 1fr); }
  .offers-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
  .nav-inner { gap: 12px; }
  .nav-tab { padding: 6px 10px; font-size: 0.8rem; }
  .hero h1 { font-size: 1.75rem; }
  .search-bar { flex-direction: column; }
  .search-btn { width: 100%; }
  .trust-badges-inner { grid-template-columns: 1fr; }
  .dest-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: repeat(2, 1fr); }
  .explore-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .credit-promo { flex-direction: column; text-align: center; }
  .loyalty-cta h2 { font-size: 1.4rem; }
}

@media (max-width: 480px) {
  .dest-grid { grid-template-columns: 1fr; }
  .deals-grid { grid-template-columns: 1fr; }
  .explore-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .property-card { min-width: 220px; max-width: 220px; }
}

/* ===== Utility ===== */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
}

